ALTER POLICY "sales_tenant_insert" ON "sales" TO authenticated WITH CHECK (tenant_id = (select auth.jwt() -> 'app_metadata' ->> 'tenant_id')::uuid and public.is_current_user_tenant_member(tenant_id) and public.is_current_user_tenant_owner(tenant_id) or tenant_id = (select auth.jwt() -> 'app_metadata' ->> 'tenant_id')::uuid and public.is_current_user_tenant_member(tenant_id) and public.is_current_user_tenant_member(tenant_id) and not public.is_current_user_tenant_owner(tenant_id) and internal_notes is null and sold_by = (select auth.uid()));